// data/religious-stories-extra.ts
// ============================================================================
// Bundled "religious stories" beyond prophets & companions.
// Source: Qur'an, Sahih Hadith (Bukhari, Muslim, Ahmad), Sira (Ibn Hisham,
// Ibn Kathir), and well-attested Islamic history. No Israiliyyat unless
// flagged. Folkloric/secular tales (Antarah, Mutanabbi, Madinat al-Nuhas,
// Abu Zayd al-Hilali, Harb al-Basus) are intentionally omitted.
//
// Each entry mirrors the Firestore CMSReligiousStory shape and is consumed
// from three places:
//   1. lib/content-api.ts   — merged with Firestore docs (Firestore wins
//      per-id), so users see stories immediately without admin work.
//   2. data/religious-story-complete.ts — exposes the same transcripts to
//      the "expansion" path used when admins type shorter text.
//   3. admin-panel/src/data/religious-story-presets.ts — exposes each entry
//      as a searchable preset the admin can apply to a new Firestore record.
//
// audioUrl is intentionally empty; admins attach audio later from the panel.
// ============================================================================

// Citation for a specific claim or section of a story. Mirrors StorySource
// in lib/content-api.ts so the bundled seed and Firestore docs share one
// shape. `note` is for flagging ikhtilaf or weak chains the reader should
// know about even when the named source is authentic.
export interface StorySourceEntry {
  reference: string;
  url?: string;
  note?: string;
}

export interface ExtraReligiousStory {
  id: string;
  label: string;             // short Arabic label for admin preset list
  title: string;             // Arabic title shown to users
  titleEn: string;
  brief: string;             // Arabic 1-line summary
  briefEn: string;
  icon: string;              // MaterialCommunityIcons name (mobile + admin)
  order: number;             // default sort order
  transcript: string;        // full Arabic body, paragraphs joined by \n\n
  transcriptEn: string;
  sourceUrl?: string;        // legacy single canonical URL
  sources?: StorySourceEntry[]; // structured citations shown under the story
}

function P(parts: string[]): string {
  return parts.join('\n\n');
}

